"""Small synthetic OOXML fixtures; no production documents or extra packages."""
from pathlib import Path
from zipfile import ZipFile, ZIP_DEFLATED
import sys
root=Path(sys.argv[1]);root.mkdir(parents=True,exist_ok=True)
def package(name,files):
    with ZipFile(root/name,'w',ZIP_DEFLATED) as archive:
        for path,text in files.items():archive.writestr(path,text)
rel='http://schemas.openxmlformats.org/package/2006/relationships'
office='http://schemas.openxmlformats.org/officeDocument/2006/relationships'
def rels(rows):return '<Relationships xmlns="'+rel+'">'+''.join('<Relationship Id="'+i+'" Type="'+office+'/'+kind+'" Target="'+target+'"/>' for i,kind,target in rows)+'</Relationships>'
def ct(parts):return '<Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types"><Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/><Default Extension="xml" ContentType="application/xml"/>'+''.join('<Override PartName="/'+p+'" ContentType="application/vnd.openxmlformats-officedocument.'+t+'+xml"/>' for p,t in parts)+'</Types>'
package('sample.docx',{'[Content_Types].xml':ct([('word/document.xml','wordprocessingml.document.main')]),'_rels/.rels':rels([('rId1','officeDocument','word/document.xml')]),'word/document.xml':'<w:document xmlns:w="http://schemas.openxmlformats.org/wordprocessingml/2006/main"><w:body><w:p><w:r><w:t>DSH Office Word fixture</w:t></w:r></w:p><w:sectPr><w:pgSz w:w="11906" w:h="16838"/><w:pgMar w:top="1440" w:right="1440" w:bottom="1440" w:left="1440"/></w:sectPr></w:body></w:document>'})
package('sample.xlsx',{'[Content_Types].xml':ct([('xl/workbook.xml','spreadsheetml.sheet.main'),('xl/worksheets/sheet1.xml','spreadsheetml.worksheet')]),'_rels/.rels':rels([('rId1','officeDocument','xl/workbook.xml')]),'xl/_rels/workbook.xml.rels':rels([('rId1','worksheet','worksheets/sheet1.xml')]),'xl/workbook.xml':'<workbook xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main" xmlns:r="'+office+'"><sheets><sheet name="Sheet1" sheetId="1" r:id="rId1"/></sheets></workbook>','xl/worksheets/sheet1.xml':'<worksheet xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main"><sheetData><row r="1"><c r="A1" t="inlineStr"><is><t>DSH Office Excel fixture</t></is></c><c r="B1"><v>42</v></c></row></sheetData></worksheet>'})
package('sample.pptx',{'[Content_Types].xml':ct([('ppt/presentation.xml','presentationml.presentation.main'),('ppt/slides/slide1.xml','presentationml.slide')]),'_rels/.rels':rels([('rId1','officeDocument','ppt/presentation.xml')]),'ppt/_rels/presentation.xml.rels':rels([('rId1','slide','slides/slide1.xml')]),'ppt/presentation.xml':'<p:presentation xmlns:p="http://schemas.openxmlformats.org/presentationml/2006/main" xmlns:r="'+office+'"><p:sldIdLst><p:sldId id="256" r:id="rId1"/></p:sldIdLst><p:sldSz cx="12192000" cy="6858000"/><p:notesSz cx="6858000" cy="9144000"/></p:presentation>','ppt/slides/slide1.xml':'<p:sld xmlns:p="http://schemas.openxmlformats.org/presentationml/2006/main" xmlns:a="http://schemas.openxmlformats.org/drawingml/2006/main"><p:cSld><p:spTree><p:nvGrpSpPr><p:cNvPr id="1" name=""/><p:cNvGrpSpPr/><p:nvPr/></p:nvGrpSpPr><p:grpSpPr/><p:sp><p:nvSpPr><p:cNvPr id="2" name="Title"/><p:cNvSpPr/><p:nvPr/></p:nvSpPr><p:spPr><a:xfrm><a:off x="914400" y="914400"/><a:ext cx="9000000" cy="1000000"/></a:xfrm><a:prstGeom prst="rect"><a:avLst/></a:prstGeom></p:spPr><p:txBody><a:bodyPr/><a:lstStyle/><a:p><a:r><a:t>DSH Office PowerPoint fixture</a:t></a:r></a:p></p:txBody></p:sp></p:spTree></p:cSld><p:clrMapOvr><a:masterClrMapping/></p:clrMapOvr></p:sld>'})
(root/'sample.md').write_text('# DSH Office Markdown fixture\n\n可编辑的文档。\n')
print('Created four synthetic documents.')
